EXPECTED_SPARSE = {
    "mean": 66.67,     # 400 / 6
    "std": 83.67,      # 手算
    "cv": 1.2550,
}

# ============================================================================
# MAD 預期結果
# ============================================================================

# SERIES_WITH_UPPER_OUTLIER 的 MAD 驗算
# non-zero = [100, 120, 80, 110, 90, 800]
# sorted = [80, 90, 100, 110, 120, 800]
# median = (100 + 110) / 2 = 105
# abs_devs from median: |80-105|=25, |90-105|=15, |100-105|=5, |110-105|=5, |120-105|=15, |800-105|=695
# abs_devs sorted = [5, 5, 15, 15, 25, 695]
# MAD = (15 + 15) / 2 = 15.0
# sigma_eq = 15.0 * 1.4826 = 22.239
# upper = 105 + 3 * 22.239 = 171.717
# lower = 105 - 3 * 22.239 = 38.283
# outlier: 800 > 171.717 (upper)
MAD_UPPER_OUTLIER_EXPECTED = {
    "median": 105.0,
    "mad": 15.0,
    "upper_bound": 171.72,
    "lower_bound": 38.28,
    "outlier_count": 1,
    "outlier_values": [800.0],
    "outlier_bounds": ["upper"],
}

# SERIES_IDENTICAL_PLUS_OUTLIER 的 MAD 驗算
# non-zero = [100, 100, 100, 100, 5000]
# sorted = [100, 100, 100, 100, 5000]
# median = 100
# abs_devs = [0, 0, 0, 0, 4900] sorted = [0, 0, 0, 0, 4900]
# MAD = 0 → 跳過偵測（50%+ 值相同）
MAD_IDENTICAL_OUTLIER_EXPECTED = {
    "mad": 0.0,
    "outlier_count": 0,  # MAD = 0 時不做偵測
}

