# [2] (100+120+80)/3 = 100
# [3] (120+80+110)/3 = 103.33
# [4] (80+110+90)/3 = 93.33
MA_NORMAL_EXPECTED = [100.0, 110.0, 100.0, 103.33, 93.33]
